"""Predicate semantics: explicit scopes, witnesses, countermodels and domain limits."""
import manual_solutions as author

def put(n,steps,errors):
 author.add('DM2T',f'004-{n:03}',steps,errors,'逐小问核对个体域、量词顺序、自由出现赋值及成真见证、成假反例。')
def example(n,steps,errors,solution=None):
 author.add_example('DM2T',n,steps,errors,'按原题所需谓词元数、量词辖域和解释逐项求值；非永真性给完整反模型。')
 if solution is not None:author.PATCHES['SRC-DM2T-X'+n]['solution']=solution

put(1,[r'0元谓词不含个体变项，直接代表一个完整命题。每小问单独定义P、Q，再由“和、除非、仅当、不是、或”选联结词。',r'第（1）P为“小王学过英语”，Q为“小王学过法语”，“和”要求两者同时，故P∧Q。第（2）P为“李健是东北人”，Q为“李健怕冷”；“除非P，否则Q”表示非P时一定Q，即¬P→Q，消箭头等值于P∨Q。',r'第（3）P为“2>3”，Q为“2>4”，“P仅当Q”把Q当必要条件，故P→Q，不能按两句话的真假改变翻译方向。第（4）P为“3是偶数”，式¬P。',r'第（5）P为“2是素数”、Q为“3是素数”，“或”取相容析取P∨Q，两项都真也允许，不能擅自改成恰一真。'],[r'“仅当”的后半句是必要条件，放箭头后件。',r'“除非P否则Q”是¬P→Q，不是P→Q。'])
put(2,[r'令E(x)表示“x能被2整除”。当域已经是Z，“整数”的范围已由量词限定，不需要再加特性谓词。两式分别为∀xE(x)、∃xE(x)。',r'对Z中全称式，找整数1：1不能被2整除，因此一个反例即使全称式假；存在式取见证2=2·1成立，故真。',r'域改R时，量词遍历所有实数，先令I(x)表示“x是整数”。“凡整数”写∀x(I(x)→E(x))，仅对整数提出要求；“有的整数”写∃x(I(x)∧E(x))，见证必须同时属于整数且满足整除。',r'全称式仍被实数域内的整数1否定，存在式仍取整数2，故真值仍假、真。非整数使全称条件前件假，不构成反例；存在式不能靠选非整数使条件蕴涵真而冒充整数见证。'],[r'全称限制用蕴涵，存在限制用合取。',r'扩大域后若忘I(x)，就把“整数”要求误套到所有实数。'])
put(3,[r'把完整等式解释为域上的一元谓词：F(x)为x²−2=(x+√2)(x−√2)，G(x)为x+5=9。所需式为∀xF(x)、∃xG(x)。',r'乘开右边：x²−(√2)²=x²−2，所以F对任意实数恒真，特别对每个自然数也真。因此两个域的全称式都真。',r'解G得x=4，4既属于N也属于R；分别取4作见证，两个存在式都真。不必全域枚举，只需合法见证。',r'严格的一阶解释要求常项指向域内元素；N域中√2不是自然数，故这里将整个数值判定作为已解释的一元F，不把√2单独设成指向N元素的常项。取F在N上的限制即可，原恒等式的数值运算在实数中解释。'],[r'自然数域不含√2，应明确整句谓词解释，避免不合法的域内常项。',r'存在式的解必须在所选域内，本题4合法。'])
put(4,[r'第（1）域取数，Q(x)为有理数、R(x)为可写成分数。“没有不能……”先写¬∃x(Q(x)∧¬R(x))；移否定得∀x(Q(x)→R(x))。否定的是“存在有理数且不可表示”的反例。',r'第（2）域取人，B为在北京卖菜、W为外地人。“不全是”是¬∀x(B(x)→W(x))，量词否定、蕴涵否定化为∃x(B(x)∧¬W(x))，只承诺至少一个非外地人，不说所有人都非外地人。',r'第（3）域取物体，C为乌鸦、H为黑，式∀x(C(x)→H(x))。这仅把黑色要求施于乌鸦，非乌鸦无需黑。',r'第（4）用包含人和日期的域，P(x)为人、T(t)为日期、E(x,t)为当天锻炼。先选同一个人再覆盖所有日期：∃x(P(x)∧∀t(T(t)→E(x,t)))。若交换为∀t∃x，每天可以换一个人，语义已不同。'],[r'“不全”是至少一个反例，“全不”才是所有都不。',r'“有的人天天”先∃人后∀日，不能允许见证随日期变化。'])
put(5,[r'域取交通工具，T火车、S轮船、C汽车，F(x,y)表示x比y快，参数位置先快者后慢者。',r'第（1）任意火车和任意轮船都要满足，写∀x∀y((T(x)∧S(y))→F(x,y))。两个类别条件放同一前件。',r'第（2）有一列火车、至少一辆汽车构成快于关系，写∃x∃y(T(x)∧C(y)∧F(x,y))。三个条件必须由同一对见证同时满足。',r'第（3）先写“汽车x比所有火车快”为C(x)∧∀y(T(y)→F(x,y))，再否定存在这种汽车：¬∃x(C(x)∧∀y(T(y)→F(x,y)))。在有汽车的情况下也可读成每辆汽车都有一列不被它超过的火车。',r'第（4）“汽车比火车慢”写F(火车,汽车)，所以否定全称∀x∀y((C(x)∧T(y))→F(y,x))。推否定得到∃x∃y(C(x)∧T(y)∧¬F(y,x))，不快于不必等于反向严格更快，也可能同速。'],[r'F的两个参数有方向，慢于须交换快者、慢者位置。',r'¬F(y,x)不必推出F(x,y)，不可默认速度无并列。'])
put(6,[r'域固定R。第（1）∀x∃y(xy=0)为真：无论先给何x，均可选y=0；允许见证依赖x，但本题恰可统一选0。',r'第（2）∃x∀y(xy=0)也真：先选固定x=0，则对所有实数y均成立。量词次序不同，只是这一个关系下碰巧两式都真。',r'第（3）∀x∃y(y=x+1)真，给任意实数x，用y=x+1仍为实数。第（4）∀x∀y(xy=yx)真，由实数乘法交换律。',r'第（5）∀x∀y(xy=x+y)假，取x=y=1得到1=2，反例足以否定。第（6）∀x∃y(x²+y²<0)假，因任意实数平方非负，尤其x=0时任何y都不能满足，存在后件失败。'],[r'两个量词次序的公式本题同真不表示它们一般等价。',r'否定∀x∃y只需找到一个x，使所有y都不行。'])
put(7,[r'第（1）∀x∀y∃z(x−y=z)读成“任意两个整数的差是某个整数”。先任取x、y，令z=x−y，整数减法封闭使z合法，所以真。',r'第（2）∀x∃y(xy=1)读成“每个整数都有整数乘法逆元”。取x=0，对一切整数y都有0y=0≠1，全称式假；也可取x=2，其实数解1/2不在Z。',r'第（3）∃x∀y∀z(x+y=z)要一个固定x同时满足所有y、z。若有此x，取y=0,z=0得x=0，再同样y=0,z=1得x=1，矛盾，故假。这比∃x∀y∃z强得多。'],[r'不同整数y,z任意，不能让z永远只取x+y后就假装满足∀z。',r'整数域中的见证必须是整数，1/2不合法。'])
put(8,[r'判断一次出现是否受约束，要找该出现所在的量词辖域及匹配变元；同一字母在别处可以是自由出现。第（1）∀x指导x，辖域为括号内F(x)→G(x,y)，F、G中两个x均受约束，G的y自由。自由变项集合{y}。',r'第（2）最高层是蕴涵，左∀x只管F(x,y)，右∃y只管G(x,y)。左F的x约束、y自由；右G的x自由、y约束。因此自由集合{x,y}，二字母各有一次自由、一次约束出现。',r'第（3）最高层为析取。左∀x辖域是∃y(F(x,y)∧G(y,z))，其下∃y辖域F(x,y)∧G(y,z)；F中的x、y与G中的y均约束，G的z自由。',r'右∃x只辖H(x,y,z)，其中x约束，y、z自由。全式x自由0次约束2次，y自由1次约束2次，z自由2次约束0次；自由集合{y,z}。量词后作为指导变元的字母不是这里对原子公式内出现次数的额外计数。'],[r'量词不会跨最外层蕴涵或析取自动作用于另一分支。',r'不能笼统说“y是约束变元”而漏掉另一处自由y。'])
put(9,[r'先记住只有自由出现使用σ(x)=1、σ(y)=−1；受量词约束的同名字母随域遍历，不能继续强塞旧赋值。f解释为差，F为相等，G为小于。',r'第（1）改名避免遮蔽：∀u(u<−1→∃v(u=v))。每个u的存在后件都可取v=u，故蕴涵恒真，全称式真。这里外部自由y=−1与内层存在v不是同一取值。',r'第（2）改名为∀v(1−v=0→∀u(u<v))。取v=1，前件真，而u=1已否定“所有u<1”，所以全称式假。',r'第（3）解释为(∃u(u<−1))→∀v(1−v=0)。前件取u=−2成立；后件取v=0得1=0失败，故真→假为假。',r'第（4）解释为∀v(1−v<0)→∃u(u=−1)。左全称式被v=0否定，右存在式取u=−1真，所以假→真为真。真值依次真、假、假、真。'],[r'内层同名量词重新绑定该出现，改成新字母最易看清。',r'蕴涵前件假时整式真，不应判“无意义”。'])
put(10,[r'本书N含0，按这个域解释。只有自由x、y、z分别固定2、3、4；量词绑定的同名出现要另行赋值，a=2、f为加法、g为乘法。',r'第（1）∀u(2u=3)假，u=0得0≠3。第（2）改名后为(∃u(u+2=3))→∃v(v+2=2)：左有u=1，右有v=0，两者真，蕴涵真。',r'第（3）∀u∀v∃w(u+v=w)真，取w=u+v，自然数加法封闭保证见证合法。第（4）∃u(u+3=4u)，解得u=1，属于N，所以真。',r'结果假、真、真、真。若误把N定义为正整数，第（2）后件会丢掉0的见证而改变结果，因此域约定必须随解释一并保留。'],[r'本书自然数含0，不应另套正整数约定。',r'第（2）后件x是自由出现，仍取2，不受左边∃x约束。'])
put(11,[r'分类中“永真”要在任意非空域、解释和自由赋值下都真；“矛盾”要全部都假；其余若有一个成真解释且有一个成假解释，为非永真的可满足式。',r'第（1）把F(x,y)视为p、G(x,y)视为q，式p→(q→p)：p假时外蕴涵真，p真时内蕴涵后件真，故永真。第（2）∀x(F(x)→F(x))恒真，∃y(G(y)∧¬G(y))恒假，真→假恒假，故矛盾。',r'第（3）成真取D={0}且F全真。成假取D={0,1}、F(x,y)当且仅当x=y：每个x可选y=x使前件∀x∃y真，但没有固定x能同时等于0和1，后件∃x∀y假。因此非永真的可满足式。',r'第（4）若∃x∀yF(x,y)真，选固定见证c，则每个y都可取x=c，后件∀y∃x真；前件假时蕴涵也真，所以永真。',r'第（5）成真取D={0}、F全真。成假取D={0,1}且F仅含有序对(0,1)：x=0,y=1使F(x,y)真而F(y,x)假，全称式假。因此非永真的可满足式。',r'第（6）令A=∀xF(x)、B=∃yG(y)，式¬(A→B)∧B≡A∧¬B∧B恒假，故矛盾。整个量词子式可当命题块，但不同量词结构一般不能任意当独立同值块。'],[r'∀x∃y允许见证随x变，不能推固定一个x适应所有y。',r'证非永真可满足要同时给成真与成假解释，只给反例不足以排除矛盾式。'])
put(12,[r'第（1）成真取D={0}、F={0}；成假取D={0,1}、F={0}、自由赋值x=0。F(x)真但∀uF(u)被u=1否定，故非永真的可满足式。量词内x与自由x应分开理解。',r'第（2）同样D={0}、F={0}成真；取D={0,1}、F={0}、自由x=1，则∃uF(u)取0真，但F(1)假，所以也是非永真的可满足式。',r'第（3）任意解释中，若∀x(F→G)及∀xF均真，对任意个体d先得F(d)→G(d)及F(d)，假言推理得G(d)，故∀xG真。任一相应蕴涵前件假也使整式真，所以永真。',r'第（4）成真令单元素域F、G全真。成假取D={0,1}、F={0}、G=∅：∀F假使(∀F→∀G)真；但0处F真G假使∀x(F→G)假，外层真→假。故非永真的可满足式。'],[r'第（1）、（2）含自由x，反模型必须指定它的值。',r'“全称条件推出全称结论”与“逐个点的条件”不可以无条件反向互推。'])
put(13,[r'三小问均可用同一个非空单元素域D={a}，指定所有出现的一元谓词在a处、二元谓词在(a,a)处的真值。此时∀与∃都只检查唯一元素，但联结词规则保持不变。',r'第（1）∀x(F(x)∨G(x))：成真令F(a)=1,G(a)=0，唯一析取1∨0=1；成假令两者0，唯一析取为0。',r'第（2）∃x(F∧G∧H)：成真令F(a)=G(a)=H(a)=1，a为见证；成假令F(a)=0、G(a)=H(a)=1，唯一候选合取为0，无见证。',r'第（3）∃x(F(x)∧∀y(G(y)∧H(x,y)))：成真令F(a)=G(a)=H(a,a)=1，内全称与外存在都真；成假令F(a)=1,G(a)=0,H(a,a)=1，内合取0，外部唯一候选失败。这些赋值完整定义了本式涉及的谓词。'],[r'成假存在式要让所有候选失败，单元素域便于完整核查。',r'二元H应写明H(a,a)，不能只写含义不清的H(a)。'])
put(14,[r'需对每个公式分别展示成真解释和成假解释；存在成真解释排除矛盾，存在成假解释排除永真。统一用非空域D={a}。',r'第（1）成真令F(a)=0,G(a)=0,H(a,a)=0：唯一外蕴涵前件假，故全式真。成假令F(a)=1,G(a)=0,H(a,a)=0：∃y(G(y)∧H(a,y))无见证，唯一外蕴涵真→假，所以全式假。',r'第（2）成真令F(a)=0,G(a)=1,H(a,a)=0：唯一前件F(a)∧G(a)=0，蕴涵真。成假令F(a)=G(a)=1,H(a,a)=0，唯一蕴涵1→0为假，全称式假。',r'故两式均不是永真式，也不是矛盾式。这里构造的是纯逻辑解释，不要求这些谓词另具现实性质。'],[r'成真全称蕴涵可通过假前件实现，不能只尝试把每个原子都设真。',r'两式需要各自一对解释，不是用一式的例子直接替另一式。'])

example('072-6909',[r'题目要求0元谓词，所以直接令P表示完整句“2是素数”、Q表示“4是素数”。“只有P才Q”把P作必要条件，式为Q→P。P真Q假，故0→1=1。',r'第（2）另令R为“5>4”、S为“4>6”，式R→S。R真S假，故1→0=0。',r'两个小问均无量词与自由变项；也能用一元素数谓词或二元大于谓词写原子实例，但那不是本题明确要求的0元表示。'],[r'“只有”后是必要条件P，箭头应Q→P。',r'不能用含参数的一元或二元谓词替代题指定的0元谓词答案。'],r'令0元谓词P：“2是素数”、Q：“4是素数”、R：“5>4”、S：“4>6”。（1）$Q\to P$，真；（2）$R\to S$，假。')
example('073-3757',[r'在人类域中所有量词对象已是人。令F为呼吸、G为左手写字，分别∀xF(x)、∃xG(x)。无需再通过“是人”筛选。',r'在全总域中令M为人。第一句只要求人呼吸，写∀x(M(x)→F(x))；不是∀x(M(x)∧F(x))，后者会强迫域中所有东西都是人。',r'第二句要求真见证同时是人且左手写字，写∃x(M(x)∧G(x))。若改蕴涵，选一块非人的石头便会让前件假、蕴涵真，不能表达有人左手写字。'],[r'域中已限定的类别不必重复，但换全总域必须补类别谓词。',r'存在量词的类别限制使用合取。'])
example('074-3540',[r'令F(x)为所给恒等式、G(x)为x+5=3，式分别∀xF(x)、∃xG(x)。两域采用相同句法，真值随解释域而定。',r'展开(x−1)(x−2)=x²−3x+2，对所有实数成立，所以其在N、R上的限制都恒真，两个全称式真。',r'G的唯一实数解x=−2。−2不属于N，故自然数域存在式假；−2属于R，故实数域取这个见证为真。不能因在实数中解出一个值就忽略域限制。'],[r'真值判定不只看方程可解，还要看见证是否落在指定域。',r'恒等式对每个实数成立，因此自动对其自然数子域成立。'])
example('074-7390',[r'按教材给出的事实语境，域取全总域，M为人。第（1）∀x(M(x)→F(x))，F为黑发；教材以非黑发者为反例判假。“全都”只需一反例即可否定。',r'第（2）G为登上过月球，写∃x(M(x)∧G(x))；教材给1969年阿姆斯特朗为见证，判真。见证要同时满足人和登月两个条件。',r'第（3）H为登上过木星，写¬∃x(M(x)∧H(x))，等值∀x(M(x)→¬H(x))；教材事实设定下不存在见证，判真。这是事实语境的判断，不是该公式仅凭形式就永真。',r'第（4）F为在美国留学的学生、G为亚洲人，式¬∀x(F(x)→G(x))≡∃x(F(x)∧¬G(x))。教材设定有非亚洲留学生，判真；“未必都是”只需这样一个见证，不表示全部非亚洲。'],[r'事实解释下为真与逻辑永真不同，不能以一个事实语境概括所有解释。',r'“没有人”是否定存在，“不全是”是存在反例，两者范围不同。'])
example('075-4020',[r'用F兔子、G乌龟、H(x,y)为x比y快、L(x,y)为同速。第（1）按本题全称读法：∀x∀y((F(x)∧G(y))→H(x,y))，每对兔龟均须满足。',r'第（2）先挑一只固定兔子，再管全部乌龟：∃x(F(x)∧∀y(G(y)→H(x,y)))。这与每只乌龟各有一只更快兔子的∀y∃x结构不同。',r'第（3）把第一式整体否定，化成∃x∃y(F(x)∧G(y)∧¬H(x,y))，表示至少一对兔龟不满足严格更快，不等于所有兔子都慢。',r'第（4）两只须为不同个体，故¬∃x∃y(F(x)∧F(y)∧x≠y∧L(x,y))。若漏x≠y，同一只兔子与自身同速通常就会违反结论，语义改变。'],[r'“有的兔子比所有乌龟快”要求同一只兔子，量词次序不能交换。',r'“两只兔子”需显式排除x=y。'])
example('077-7227',[r'第（1）∀x指导x，辖域F(x,y)→G(x,z)，其中x在F、G共两次均约束，y一次自由、z一次自由，自由集合{y,z}。',r'第（2）外层蕴涵把两支分开。左∀x只辖F(x)→G(y)，F的x约束，G的y自由；右∃y只辖H(x)∧L(x,y,z)，L的y约束，H与L的两个x均自由，z自由。',r'因此整式x自由2次、约束1次；y自由1次、约束1次；z自由1次、约束0次。各量词的指导字母只说明绑定对象，出现次数这里统计原子公式参数中的出现。'],[r'左∀x不会跨蕴涵去绑定右侧H、L的x。',r'一个字母可同时有自由与约束出现，需逐位置标注。'])
example('078-5422',[r'第（1）把f、a、F代入，得∃x(2x+1=0)，唯一实数解−1/2。R域取此见证为真；N域中2x+1≥1，没有解，假。',r'第（2）∀xG(x,y)只有x被绑定，y自由，所以指定域和G含义之后仍需给y赋值。其语义为“所有自然数x都≥所给y”。',r'本书N含0。赋y=0时每个自然数均≥0，全称真；赋y=1时x=0违反0≥1，全称假。这展示同一个含自由变项公式会随赋值改变真值。'],[r'解释与自由赋值是两部分；有自由y不能只靠谓词定义唯一确定真值。',r'不能把自然数域的0悄悄排除。'])
example('079-3641',[r'只对自由出现用x=1,y=2,z=3；a=0，f加法、g乘法、F相等。第（1）1+2=1·2即3=2，假；第（2）(1+0=2)→(1·2=3)，前件假，故蕴涵真；第（3）否定1·2=2·3，即2≠6，真。',r'第（4）∀u(2u=3)被u=0否定，假。第（5）改名为(∀u(u·0=u))→(1=2)，左被u=1否定，右假，故0→0真。第（6）就是这一左全称式，假。',r'第（7）∀u∀v((u+0=v)→(v+0=u))真，因为前件为u=v时后件v=u由等号对称成立，前件假时也真。第（8）∀u∀v∃w(u+v=w)真，自然数加法封闭，见证w=u+v。',r'第（9）∃u(2u=u²)，移项u(u−2)=0，u=0与2均为合法自然数见证，故真。按序假、真、真、假、真、假、真、真、真。'],[r'第（5）右侧自由x取1，不受左边∀x覆盖。',r'由固定赋值计算原子式与对整个域量化是两种不同工作。'])
example('080-6390',[r'第（1）用单元素域D={a}，自由y也赋a。F(a)=0,G(a,a)=0使唯一蕴涵真；F(a)=1,G(a,a)=0使它假。两解释证明既非永真也非矛盾。',r'第（2）同域自由y=a，F(a)=G(a,a)=1时a为存在见证，真；改F(a)=0,G(a,a)=1时唯一候选失败，假，故同属非永真的可满足式。',r'第（3）令p=∀xF(x)、q=∃x∃yG(x,y)，式p→(q→p)。p假则外蕴涵真；p真则内后件真，所以对任意解释、赋值都真，是永真式。',r'第（4）令p=∀xF(x)、q=∃yG(y)，式¬(p→q)∧q≡p∧¬q∧q=0，对任意解释都假，故矛盾式。单元素模型只用于前两问的存在性证明，后两问的全称分类来自一般推导。'],[r'有限模型中测试到真不能证明永真，只能证明可满足。',r'含自由y的反模型要明确给y的值。'])
example('081-1340',[r'取任意非空域D、任意解释及赋值，逐条证明前件真则后件真；前件假时蕴涵直接为真。第（1）若∀xF(x)真，因D非空可任取d∈D，再由全称得F(d)，以d见证∃xF(x)。非空条件在此不可删。',r'第（2）全称覆盖D每个元素，尤其赋值σ(y)∈D，故F(y)真。第（3）常项c解释成D中某个cᴵ，全称覆盖它，故F(c)真。',r'第（4）若F(y)真，取d=σ(y)为存在见证；第（5）若F(c)真，取常项所指cᴵ为见证。两式同样在任意解释和赋值下成立。',r'因此五式均永真。第二、四式中y虽自由，证明针对任意σ(y)，已覆盖所有自由赋值；不必擅自在外层增加量词才讨论其有效性。'],[r'从∀推出∃需非空域；空域下前者可真、后者假。',r'全称实例化取的值要来自域，常项及赋值按一阶解释保证这一点。'])

